// Draws the dashboard page.
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const q = $('Open dashboard').first().json.query || {};
const day = q.day || $now.setZone('Asia/Kolkata').toISODate();
const status = q.status || 'all';
const leads = $('Get leads').all().map(i => i.json).filter(r => r.id);
const dms = $input.all().map(i => i.json).filter(r => r.id);
const back = `/webhook/dashboard?day=${encodeURIComponent(day)}&status=${encodeURIComponent(status)}`;
const statuses = ['all', 'ready_to_send', 'review', 'rejected', 'sent', 'error', 'processing'];
const count = s => leads.filter(l => l.status === s).length;
const badge = s => `<span class="b b-${esc(s)}">${esc(String(s).replace(/_/g, ' '))}</span>`;
const yes = (v, label, href) => v ? (href ? `<a href="${esc(href)}" target="_blank">${label}</a>` : label) : '<span class="muted">–</span>';

const rows = leads.map(l => `<tr>
<td><input type="checkbox" class="pick" value="${l.id}"></td>
<td><b>${esc(l.name)}</b><div class="muted">${esc(l.category || '')}</div></td>
<td>${esc(l.city || '')}</td><td>${badge(l.status)}</td>
<td class="n">${l.website_score ?? '<span class="muted">–</span>'}</td><td class="n">${l.enrichment_score ?? '<span class="muted">–</span>'}</td>
<td>${yes(l.email, 'Email')} ${yes(l.instagram, 'Insta', l.instagram)} ${yes(l.facebook, 'FB', l.facebook)}</td>
<td>${l.has_page ? `<a href="/webhook/page?id=${l.id}" target="_blank">View</a>` : '<span class="muted">none</span>'}</td>
<td class="muted">${esc(l.sent_time || '')}</td></tr>`).join('');

const dmRows = dms.map(d => `<tr><td><b>${esc(d.name)}</b></td><td>${esc(d.channel)}</td>
<td><a href="${esc(d.to_address)}" target="_blank">Open profile</a></td>
<td><textarea readonly onclick="this.select()">${esc(d.message)}</textarea></td>
<td><form method="post" action="/webhook/dashboard-action"><input type="hidden" name="action" value="dm_done">
<input type="hidden" name="ids" value="${d.id}"><input type="hidden" name="back" value="${esc(back)}"><button>Done</button></form></td></tr>`).join('');

const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Cold outreach dashboard</title><style>
body{font-family:system-ui,sans-serif;margin:0;background:#f5f5f7;color:#1d1d1f}main{max-width:1200px;margin:auto;padding:24px}
h1{font-size:22px;margin:0 0 16px}h2{font-size:18px;margin:32px 0 12px}.card{background:#fff;border-radius:12px;padding:16px;box-shadow:0 1px 2px #0001}
.bar{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin-bottom:16px}.chips span{margin-right:12px}
table{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:left;padding:8px;border-bottom:1px solid #eee;vertical-align:top}
th{font-size:12px;color:#6e6e73;text-transform:uppercase}.n{text-align:center}.muted{color:#8e8e93;font-size:12px}
button{border:0;border-radius:8px;padding:8px 14px;font-weight:600;cursor:pointer;background:#e5e5ea}
.send{background:#1f6feb;color:#fff}.reject{background:#d1242f;color:#fff}.build{background:#1a7f37;color:#fff}
.b{padding:2px 8px;border-radius:999px;font-size:12px;background:#eee}.b-ready_to_send{background:#dafbe1}.b-review{background:#fff8c5}
.b-rejected{background:#ffebe9}.b-sent{background:#ddf4ff}.b-error{background:#ffebe9}
textarea{width:100%;min-height:60px;font:inherit;font-size:13px}.msg{background:#ddf4ff;padding:10px 14px;border-radius:8px;margin-bottom:16px}
</style></head><body><main>
<h1>Cold outreach dashboard</h1>
${q.msg ? `<div class="msg">${esc(q.msg)}</div>` : ''}
<form class="bar" method="get" action="/webhook/dashboard">
<label>Day <input type="date" name="day" value="${esc(day)}"></label>
<label>Status <select name="status">${statuses.map(s => `<option ${s === status ? 'selected' : ''}>${s}</option>`).join('')}</select></label>
<button>Show</button>
<span class="chips muted"><span>${leads.length} leads</span><span>${count('ready_to_send')} ready</span><span>${count('review')} review</span><span>${count('rejected')} rejected</span><span>${count('sent')} sent</span></span>
</form>
<div class="card">
<form id="act" method="post" action="/webhook/dashboard-action" class="bar">
<input type="hidden" name="action" id="action"><input type="hidden" name="ids" id="ids"><input type="hidden" name="back" value="${esc(back)}">
<label><input type="checkbox" id="all"> Select all</label>
<button type="button" class="send" data-a="send">Send</button>
<button type="button" class="build" data-a="build">Build page</button>
<button type="button" class="reject" data-a="reject">Reject</button>
<span class="muted">Send uses every channel the lead has. Leads without a page are skipped, so build the page first.</span>
</form>
<table><tr><th></th><th>Business</th><th>City</th><th>Status</th><th>Website</th><th>Enrich</th><th>Channels</th><th>Page</th><th>Sent</th></tr>
${rows || '<tr><td colspan="9" class="muted">No leads for this day and status.</td></tr>'}</table></div>
<h2>Manual DMs to send (${dms.length})</h2>
<div class="card"><table><tr><th>Business</th><th>Channel</th><th>Profile</th><th>Message (click to select, then copy)</th><th></th></tr>
${dmRows || '<tr><td colspan="5" class="muted">Nothing waiting.</td></tr>'}</table></div>
</main><script>
document.getElementById('all').onchange = e => document.querySelectorAll('.pick').forEach(c => c.checked = e.target.checked);
document.querySelectorAll('[data-a]').forEach(b => b.onclick = () => {
  const ids = [...document.querySelectorAll('.pick:checked')].map(c => c.value);
  if (!ids.length) { alert('Select at least one lead first.'); return; }
  document.getElementById('action').value = b.dataset.a;
  document.getElementById('ids').value = ids.join(',');
  document.getElementById('act').submit();
});
</script></body></html>`;
return [{ json: { html } }];

// Reads which button was pressed and which leads were selected.
const body = $('Dashboard action').first().json.body || {};
const ids = String(body.ids || '').split(',').map(Number).filter(n => Number.isInteger(n) && n > 0);
const action = String(body.action || '');
if (!['reject', 'build', 'send', 'dm_done'].includes(action)) throw new Error(`Unknown action: ${action}`);
const base = String($('Settings').first().json.page_base_url).replace(/\/$/, '');
const back = base + (String(body.back || '').startsWith('/webhook/dashboard') ? String(body.back) : '/webhook/dashboard');
const join = (url, msg) => url + (url.includes('?') ? '&' : '?') + 'msg=' + encodeURIComponent(msg);
const done = { reject: 'Rejected', build: 'Pages built for', send: 'Sending to', dm_done: 'Marked done:' }[action];
return [{ json: { action, ids, ids_pg: `{${ids.join(',')}}`, back: join(back, `${done} ${ids.length} selected.` + (action === 'send' ? ' Refresh in a few seconds to see the result.' : '')) } }];

const has = v => Array.isArray(v) ? v.some(x => has(x)) : v !== null && v !== undefined && String(v).trim() !== '';
const num = v => { const n = parseFloat(v); return Number.isFinite(n) ? n : null; };
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const page = (l, d) => {
  const services = (d.services || []).filter(has);
  const reviews = (d.top_reviews || []).filter(has).slice(0, 3);
  const photo = (d.photo_urls || []).filter(has)[0];
  const tel = String(d.phone || l.phone || '').replace(/[^\d+]/g, '');
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex"><title>${esc(l.name)}</title><style>
body{margin:0;font-family:system-ui,sans-serif;color:#1d1d1f;line-height:1.6}section{max-width:960px;margin:auto;padding:40px 20px}
.hero{background:#1f4b99 center/cover;color:#fff;text-align:center;padding:80px 20px}.hero h1{font-size:40px;margin:0 0 8px}
.btn{display:inline-block;margin-top:20px;background:#fff;color:#1f4b99;padding:12px 22px;border-radius:8px;text-decoration:none;font-weight:600}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}.card{border:1px solid #e5e5ea;border-radius:10px;padding:16px}
footer{text-align:center;color:#888;font-size:13px;padding:20px}</style></head><body>
<div class="hero"${photo ? ` style="background-image:linear-gradient(rgba(0,0,0,.5),rgba(0,0,0,.5)),url('${esc(photo)}')"` : ''}>
<h1>${esc(d.headline || l.name)}</h1><p>${esc(d.tagline || l.category || '')}</p>${tel ? `<a class="btn" href="tel:${tel}">Call ${esc(d.phone || l.phone)}</a>` : ''}</div>
${d.about ? `<section><h2>About</h2><p>${esc(d.about)}</p></section>` : ''}
${services.length ? `<section><h2>What we offer</h2><div class="grid">${services.map(x => `<div class="card">${esc(x)}</div>`).join('')}</div></section>` : ''}
${reviews.length ? `<section><h2>What customers say${d.rating ? ` (${esc(d.rating)} stars)` : ''}</h2><div class="grid">${reviews.map(x => `<div class="card">&ldquo;${esc(x)}&rdquo;</div>`).join('')}</div></section>` : ''}
<section><h2>Visit us</h2><p>${esc(l.address)}</p></section>
<footer>Free concept preview for ${esc(l.name)}</footer></body></html>`;
};

// Force build: makes a page from whatever enrichment data the lead has.
const out = [];
for (const { json: l } of $input.all()) {
  if (!l.id) continue;
  let d = {};
  try { d = typeof l.enrichment === 'string' ? JSON.parse(l.enrichment) : (l.enrichment || {}); } catch (e) {}
  out.push({ json: { id: l.id, landing_html: page(l, d) } });
}
return out.length ? out : [{ json: { id: null, landing_html: '' } }];

parameters.query:
SELECT id, name, email, coalesce(landing_html, '') <> '' AS has_page,
  enrichment->>'instagram_url' AS instagram, enrichment->>'facebook_url' AS facebook
FROM leads WHERE id = ANY($1::int[]);

parameters.jsCode:
// One item per message: email goes out automatically, Instagram / Facebook go to the manual DM list.
const s = $('Settings').first().json;
const out = [];
for (const { json: l } of $input.all()) {
  if (!l.id || !l.has_page) continue;
  const link = `${String(s.page_base_url).replace(/\/$/, '')}/webhook/page?id=${l.id}`;
  const text = `Hi ${l.name} team! I made a free preview of a simple website for your business: ${link} - happy to put it live on your own domain if you like it. ${s.sender_name}`;
  if (l.email) {
    const to = s.test_mode ? s.test_email : l.email;
    out.push({ json: { lead_id: l.id, channel: 'email', to,
      subject: (s.test_mode ? `[TEST - real: ${l.email}] ` : '') + `A free website preview for ${l.name}`,
      html: `<p>Hi ${l.name} team,</p><p>I put together a free preview of what a simple website for your business could look like:<br><a href="${link}">${link}</a></p><p>If you like it, I can put it live on your own domain. Just reply to this email.</p><p>${s.sender_name}</p>`,
      message: text } });
  }
  if (l.instagram) out.push({ json: { lead_id: l.id, channel: 'instagram', to: l.instagram, message: text } });
  if (l.facebook) out.push({ json: { lead_id: l.id, channel: 'facebook', to: l.facebook, message: text } });
}
return out;

// Records whether each email was sent.
const sent = $('Is email?').all(0).map(i => i.json);
return $input.all().map((item, i) => ({ json: { ...sent[i],
  status: item.json.error ? 'failed' : 'sent',
  message: item.json.error ? `${sent[i].subject}\nError: ${item.json.error.message || item.json.error}` : sent[i].subject } }));

parameters.query:
UPDATE leads SET status = 'sent', sent_at = now()
WHERE id = ANY($1::int[]) AND EXISTS (
  SELECT 1 FROM outreach o WHERE o.lead_id = leads.id AND o.status IN ('sent', 'queued'));
